 fn real(&mut self,row:&SqliteRow,index:usize)->Result<f64,ValueError>{let row=self.take("draw_scalar",row.integer(index)?)?;Reconstruction::new(self.control)?.scalar()?;FloatRow::new(row,&[FloatColumn::Binary64(1)])?.real(1)}
 fn vector<const N:usize>(&mut self,row:&SqliteRow,start:usize)->Result<[f64;N],ValueError>{let mut values=[0.0;N];for(i,value)in values.iter_mut().enumerate(){*value=self.real(row,start+i)?;}Ok(values)}
 fn list(&mut self,table:&'static str,parent:i64,index:usize,order:usize)->Result<Vec<&'a SqliteRow>,ValueError>{let key=(table,index);if !self.groups.contains_key(&key){let mut groups=BTreeMap::<i64,Vec<&SqliteRow>>::new();let source=self.rows.get(table).ok_or_else(||semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvalidValue,"unknown Draw table"))?;self.control.check_rows(source.len())?;for(i,row)in source.values().enumerate(){if !Self::null(row,index)?{groups.entry(row.integer(index)?).or_default().push(*row);}if i%256==0{self.control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,i,source.len())?;}}self.groups.insert(key,groups);}let source=self.groups.get_mut(&key).unwrap().remove(&parent).unwrap_or_default();let mut sorted=BTreeMap::new();for row in source{let order=row.integer(order)?;if order<0||sorted.insert(order,row).is_some(){return Err(semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvalidValue,"Draw duplicate or negative order"));}}let mut values=Vec::new();for(i,(order,row))in sorted.into_iter().enumerate(){if order!=ordinal(i)?{return Err(semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvalidValue,"Draw relationship order must be contiguous"));}self.take(table,row.rowid)?;values.push(row);if i%256==0{self.control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,i,0)?;}}Ok(values)}
 fn attributes(&mut self,id:i64,rule:&str)->Result<DrawingAttributes,ValueError>{let fill_rule=FillRule::parse(rule).map_err(|e|semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvalidValue,e))?;let fill=if self.has("draw_fill",id){let row=self.take("draw_fill",id)?;Some(match row.text(1)?{"solid"=>{let v=self.take("draw_fill_solid",id)?;FillStyle::Solid{color:self.vector(v,1)?}},"linearGradient"|"radialGradient"=>{let mut stops=semio_framework_value::list::PagedList::<GradientStop,{usize::MAX}>::default();for row in self.list("draw_gradient_stop",id,1,2)?{stops.push(GradientStop{offset:self.real(row,3)?,color:self.vector(row,4)?});}if row.text(1)?=="linearGradient"{let v=self.take("draw_fill_linear",id)?;FillStyle::LinearGradient{x1:self.real(v,1)?,y1:self.real(v,2)?,x2:self.real(v,3)?,y2:self.real(v,4)?,stops}}else{let v=self.take("draw_fill_radial",id)?;FillStyle::RadialGradient{cx:self.real(v,1)?,cy:self.real(v,2)?,r:self.real(v,3)?,stops}}},_=>return Err(semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvalidValue,"Draw fill variant"))})}else{None};let stroke=if self.has("draw_stroke",id){let row=self.take("draw_stroke",id)?;let dash=if Self::boolean(row,8)?{let mut values=semio_framework_value::list::PagedList::<f64,{usize::MAX}>::default();for row in self.list("draw_stroke_dash",id,1,2)?{values.push(self.real(row,3)?);}Some(values)}else{None};Some(StrokeStyle{color:self.vector(row,1)?,width:self.real(row,5)?,cap:StrokeCap::parse(row.text(6)?).map_err(|e|semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvalidValue,e))?,join:StrokeJoin::parse(row.text(7)?).map_err(|e|semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvalidValue,e))?,dash})}else{None};Ok(DrawingAttributes{fill_rule,fill,stroke})}
